#include <iostream>
using namespace std;

struct TrieNode {
    TrieNode* children[26];
    bool isEnd;
    TrieNode() : isEnd(false) {
        for (int i = 0; i < 26; i++) children[i] = nullptr;
    }
};

class Trie {
    TrieNode* root;
public:
    Trie() { root = new TrieNode(); }

    // Insert word into Trie
    void insert(string word) {
        TrieNode* node = root;
        for (char c : word) {
            int i = c - 'a';
            if (!node->children[i])
                node->children[i] = new TrieNode();
            node = node->children[i];
        }
        node->isEnd = true;
    }

    // Search for exact word
    bool search(string word) {
        TrieNode* node = root;
        for (char c : word) {
            int i = c - 'a';
            if (!node->children[i]) return false;
            node = node->children[i];
        }
        return node->isEnd;
    }

    // Check if any word starts with prefix
    bool startsWith(string prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int i = c - 'a';
            if (!node->children[i]) return false;
            node = node->children[i];
        }
        return true;
    }

    // Delete a word from Trie
    bool deleteHelper(TrieNode* node, string& word, int depth) {
        if (!node) return false;
        if (depth == word.size()) {
            if (!node->isEnd) return false;
            node->isEnd = false;
            // Check if node has no children
            for (int i = 0; i < 26; i++)
                if (node->children[i]) return false;
            return true; // safe to delete
        }
        int idx = word[depth] - 'a';
        if (deleteHelper(node->children[idx], word, depth + 1)) {
            delete node->children[idx];
            node->children[idx] = nullptr;
            // If current node is not end and has no children
            if (!node->isEnd) {
                for (int i = 0; i < 26; i++)
                    if (node->children[i]) return false;
                return true;
            }
        }
        return false;
    }

    void deleteWord(string word) {
        deleteHelper(root, word, 0);
    }
};

int main() {
    Trie trie;
    trie.insert("apple");
    trie.insert("app");

    cout << trie.search("apple") << endl;      // 1
    cout << trie.startsWith("app") << endl;     // 1

    trie.deleteWord("apple");
    cout << trie.search("apple") << endl;       // 0
    cout << trie.search("app") << endl;         // 1 (still exists)
    return 0;
}

