#include <iostream>
#include <vector>
#include <string>
using namespace std;

struct TrieNode {
    TrieNode* children[26];
    bool isEnd;
    TrieNode() : isEnd(false) {
        for (int i = 0; i < 26; i++) children[i] = nullptr;
    }
};

class AutoComplete {
    TrieNode* root;

    void dfs(TrieNode* node, string& prefix, vector<string>& results) {
        if (node->isEnd) results.push_back(prefix);
        for (int i = 0; i < 26; i++) {
            if (node->children[i]) {
                prefix.push_back('a' + i);
                dfs(node->children[i], prefix, results);
                prefix.pop_back();
            }
        }
    }

public:
    AutoComplete() { root = new TrieNode(); }

    void insert(string word) {
        TrieNode* node = root;
        for (char c : word) {
            int i = c - 'a';
            if (!node->children[i])
                node->children[i] = new TrieNode();
            node = node->children[i];
        }
        node->isEnd = true;
    }

    // Get all words with given prefix
    vector<string> getSuggestions(string prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int i = c - 'a';
            if (!node->children[i]) return {};
            node = node->children[i];
        }
        vector<string> results;
        dfs(node, prefix, results);
        return results;
    }

    // Wildcard search: '.' matches any character
    bool wildcardSearch(TrieNode* node, string& word, int idx) {
        if (!node) return false;
        if (idx == word.size()) return node->isEnd;
        if (word[idx] == '.') {
            for (int i = 0; i < 26; i++)
                if (node->children[i] && wildcardSearch(node->children[i], word, idx + 1))
                    return true;
            return false;
        }
        return wildcardSearch(node->children[word[idx] - 'a'], word, idx + 1);
    }

    bool searchWithWildcard(string word) {
        return wildcardSearch(root, word, 0);
    }
};

int main() {
    AutoComplete ac;
    ac.insert("apple"); ac.insert("app"); ac.insert("apricot");
    ac.insert("banana"); ac.insert("bat");

    // Auto-complete
    auto suggestions = ac.getSuggestions("ap");
    cout << "Suggestions for 'ap':" << endl;
    for (auto& s : suggestions) cout << "  " << s << endl;

    // Wildcard search
    cout << ac.searchWithWildcard("app.e") << endl; // 1 (apple)
    cout << ac.searchWithWildcard("b.t") << endl;   // 1 (bat)
    return 0;
}

