        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def get_suggestions(self, prefix):
        """Get all words with given prefix"""
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]

        results = []
        self._dfs(node, prefix, results)
        return results

    def _dfs(self, node, prefix, results):
        if node.is_end:
            results.append(prefix)
        for ch, child in sorted(node.children.items()):
            self._dfs(child, prefix + ch, results)

    def wildcard_search(self, word):
        """Search with '.' matching any character"""
        def _search(node, idx):
            if not node:
                return False
            if idx == len(word):
                return node.is_end
            if word[idx] == '.':
                return any(_search(child, idx + 1)
                          for child in node.children.values())
            if word[idx] not in node.children:
                return False
            return _search(node.children[word[idx]], idx + 1)

        return _search(self.root, 0)

