        for (char c : prefix.toCharArray()) {
            int i = c - 'a';
            if (node.children[i] == null) return new ArrayList<>();
            node = node.children[i];
        }
        List<String> results = new ArrayList<>();
        dfs(node, new StringBuilder(prefix), results);
        return results;
