#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define ALPHA 26
#define MAX_RESULTS 100
#define MAX_WORD 100

typedef struct TrieNode {
    struct TrieNode* children[ALPHA];
    bool isEnd;
} TrieNode;

TrieNode* createNode() {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    node->isEnd = false;
    for (int i = 0; i < ALPHA; i++) node->children[i] = NULL;
    return node;
}

void insert(TrieNode* root, const char* word) {
    TrieNode* node = root;
    for (int i = 0; word[i]; i++) {
        int idx = word[i] - 'a';
        if (!node->children[idx])
            node->children[idx] = createNode();
        node = node->children[idx];
    }
    node->isEnd = true;
}

char results[MAX_RESULTS][MAX_WORD];
int resultCount;

void dfs(TrieNode* node, char* prefix, int len) {
    if (node->isEnd) {
        prefix[len] = '\0';
        strcpy(results[resultCount++], prefix);
    }
    for (int i = 0; i < ALPHA; i++) {
        if (node->children[i]) {
            prefix[len] = 'a' + i;
            dfs(node->children[i], prefix, len + 1);
        }
    }
}

void getSuggestions(TrieNode* root, const char* prefix) {
    TrieNode* node = root;
    resultCount = 0;
    for (int i = 0; prefix[i]; i++) {
        int idx = prefix[i] - 'a';
        if (!node->children[idx]) return;
        node = node->children[idx];
    }
    char buffer[MAX_WORD];
    strcpy(buffer, prefix);
    dfs(node, buffer, strlen(prefix));
}

int main() {
    TrieNode* root = createNode();
    insert(root, "apple");
    insert(root, "app");
    insert(root, "apricot");

    getSuggestions(root, "ap");
    printf("Suggestions for 'ap':\n");
    for (int i = 0; i < resultCount; i++)
        printf("  %s\n", results[i]);
    return 0;
}
